/* @lc app=leetcode id=1696 lang=kotlin */ class Solution { fun maxResult(nums: IntArray, k: Int): Int = IntArray(nums.size).also { dp -> dp[0] = nums[0] }.let { dp -> java.util.ArrayDeque<Int>().also { dq -> dq.addLast(0) }.let { dq -> (1 until nums.size).forEach { i -> i.also { while (!dq.isEmpty() && dq.peekFirst() < i - k) dq.pollFirst() }.also { dp[i] = nums[i] + dp[dq.peekFirst()] }.also { while (!dq.isEmpty() && dp[dq.peekLast()] <= dp[i]) dq.pollLast() }.also { dq.addLast(i) } }.let { dp.last() } } } }